package abi

import (
	"math"
	"strings"

	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common/hexutil"
)

// SystemTxGas is gas limit for system txs/calls (which happen within consensus)
// and should not be limited to the local rpc gas cap or tx gas cap.
var SystemTxGas = (hexutil.Uint64)(math.MaxUint64 / 2)

var (
	vABI = mustParseABI(validatorsetABI)
	sABI = mustParseABI(stateReceiverABI)
	rABI = mustParseABI(reservedRegistryABI)
)

func ValidatorSet() abi.ABI {
	return vABI
}

func StateReceiver() abi.ABI {
	return sABI
}

func ReservedBlockspaceRegistry() abi.ABI {
	return rABI
}

